    perform action tick {
      first start;
      then assign temperatureC := io_0 * 100.0 / 1023.0;
      then assign manualLevel := io_1 * 255.0 / 1023.0;
      then assign autoSpeed := (if temperatureC <= 20.0 ? 0.0 else (if temperatureC >= 50.0 ? 255.0 else (temperatureC - 20.0) * 255.0 / 30.0));
