        first start;
        then assign modeAuto := (not modeAuto);
      }
      then assign previousPressed := io_3;
    }
    out attribute io_2 : Real = (if modeAuto ? autoSpeed else manualLevel);
    out attribute io_4 : Integer = (if modeAuto ? RealFunctions::floor(temperatureC) else RealFunctions::floor(manualLevel / 10.0));
